<script setup lang="ts">
import {computed} from 'vue'
import {rowData,type BusinessData} from '@/api/modules/business'
import {display,labels} from '@/business/labels'
import {money} from '@/api/modules/trade'
const props=defineProps<{record:BusinessData;domain:string}>()
const d=computed(()=>rowData(props.record)),notice=computed(()=>(props.record.notice||d.value.notice) as BusinessData|undefined),template=computed(()=>(d.value.template||props.record.template) as BusinessData|undefined)
const fields=computed(()=>({stock:['city','receipt_at','deadline_at','viewed_at','current_case_id'],notices:['expires_at','next_action','order_status'],auditions:['accept_by','accepted_at','departed_at','arrived_at','receipt_at','deadline_at'],conversations:['status','support_requested','support_joined'],wallet:['recorded_balance_minor','available_balance_minor','reserved_balance_minor','available_points','points_pending_reversal','qualifying_growth','membership','custody'],engagement:['growth_points','recent_growth_points','starlight','halo','level'],cocreation:['joined_count','eligible_count','people_remaining','benefit_remaining','deadline','participation_terms','credit_minor','service_code','units','expires_at'],redemption:['expires_at','effective_status','delivery','inventory_policy'],participation:['fee_minor','potential_conflict_ids','order_id','current_plan_id','current_edition_id'],privacy:['type','scopes','due_on','outcome','response','remaining_actions','request_completion'],media:['task_kind','source_kind','current_status','job_status','result']} as Record<string,string[]>)[props.domain]||[])
const assignments=computed(()=>(Array.isArray(props.record.assignments)?props.record.assignments:[]) as BusinessData[])
const relations=computed(()=>(Array.isArray(props.record.relations)?props.record.relations:[]) as BusinessData[])
const count=computed(()=>(props.record.counts||d.value.counts||{}) as BusinessData)
const boardNames:Record<string,string>={sales:'销量',reviews:'好评',repeat:'复购',popularity:'人气',levels:'成长等级',newcomers:'新人'}
const boards=computed(()=>(props.record.boards||d.value.boards||{}) as Record<string,BusinessData[]>)
const value=(key:string)=>props.record[key]??d.value[key]??count.value[key]
const facts=computed(()=>fields.value.map(key=>({key,value:value(key)})).filter(f=>f.value!==undefined&&f.value!==null&&typeof f.value!=='object'))
const request=computed(()=>(props.record.request||{}) as BusinessData),result=computed(()=>(props.record.result||{}) as BusinessData),terms=computed(()=>(typeof d.value.terms==='object'?d.value.terms:{}) as BusinessData),revenue=computed(()=>(d.value.revenue||{}) as BusinessData)
const body=computed(()=>[notice.value?.description,request.value.details,d.value.description,typeof d.value.terms==='string'?d.value.terms:terms.value.permitted_uses,revenue.value.terms,template.value?.terms,d.value.private_story,d.value.response,d.value.body].find(v=>typeof v==='string'&&v))
const amount=computed(()=>props.record.unit_minor??d.value.unit_minor??d.value.fee_minor??d.value.credit_minor??(d.value.quote as BusinessData|undefined)?.total_minor)
</script>
<template><div class="business-overview"><p v-if="body" class="business-lead">{{body}}</p><strong v-if="typeof amount==='number'" class="trade-amount">{{money(amount)}}</strong><dl class="supply-facts"><div v-for="f in facts" :key="f.key"><dt>{{labels[f.key]||f.key}}</dt><dd>{{display(f.value,f.key)}}</dd></div></dl><template v-if="notice"><p>{{display(notice.type)}} · {{notice.city}}</p><p>{{display(notice.valid_from)}} 至 {{display(notice.valid_until)}}</p><dl v-if="notice.details&&typeof notice.details==='object'" class="supply-facts"><div v-for="(v,k) in (notice.details as BusinessData)" :key="k"><dt>{{labels[k]||k}}</dt><dd>{{v}}</dd></div></dl></template><div v-if="(d.appointment||d.delivery)&&domain==='auditions'" class="business-process"><h3>本次安排与交付</h3><p v-if="d.appointment">{{(d.appointment as BusinessData).city}} · {{(d.appointment as BusinessData).venue}}<br>{{(d.appointment as BusinessData).address}}<br>{{display((d.appointment as BusinessData).starts_at)}} — {{display((d.appointment as BusinessData).ends_at)}}</p><p v-if="d.delivery">本约定取样已提交；文件查看、独立内容审核、本人收件与最终确认分别办理。</p></div><p v-if="domain==='stock'&&(record.license||d.license)" class="supply-warning">仅限本人收藏及个人社交分享 · 非商用 · 非独家 · 全球 · 永久。完整许可与排除用途见原约定。</p><template v-if="domain==='wallet'"><p class="business-muted">可用晶钻、消费成长与待冲回分别展示。累计获得口径尚未提供，暂不以余额或消费成长代替累计获得；消费、过期与退款撤回请查看原账目。</p><p class="supply-warning">充值、余额支付、提现与转账：真实托管资金服务尚未接通。</p><div class="supply-actions"><RouterLink class="button-link outline" to="/redemption/catalog">查看实际兑换资格</RouterLink><RouterLink class="button-link outline" to="/redemption/pools">查看已审奖池</RouterLink></div></template><template v-if="domain==='cocreation'"><p v-if="record.kind==='BENEFIT'" class="supply-warning">本人明确取得的不可提现服务额度，适用服务与到期以原约定为准。</p><p v-else-if="count.joined_count!==undefined">已参加 {{count.joined_count??record.joined_count??d.joined_count??'待核对'}} 人 · 有效 {{count.eligible_count??record.eligible_count??d.eligible_count??'待核对'}} 人</p><p v-if="count.joined_count!==undefined">有效人数、缺少材料与截止核定分别以服务器返回为准，报名不等于已成团或已开工。</p></template><template v-if="domain==='redemption'&&record.distribution"><h3>本奖池已审公开概率</h3><p>单抽 {{(record.config as BusinessData)?.single_points}} 晶钻 · 十连 {{(record.config as BusinessData)?.ten_points}} 晶钻</p><div v-for="(p,i) in ((record.distribution as BusinessData).prizes as BusinessData[])" :key="i" class="business-detail-item"><strong>{{p.key}}</strong><p>单抽概率：{{p.single_probability}}；第十次概率：{{p.tenth_probability}}；十连每格平均概率：{{p.average_probability_per_ten_slot}}</p></div></template><section v-if="domain==='engagement'&&Array.isArray(record.assignments)" class="business-process"><h3>{{record.staff_scope?'当前账号明确受派事项':'当前机构的实际经营范围'}}</h3><p v-if="record.scope_note" class="supply-warning">{{record.scope_note}}</p><p v-if="!record.staff_scope">有效委托 {{relations.filter(r=>r.current_status==='ACTIVE').length}} 项 · 当前可读派单 {{assignments.length}} 项</p><p v-else>当前账号明确受派 {{assignments.length}} 项</p><p v-if="typeof record.total_accrual_minor==='number'">已记录应计收入 {{money(record.total_accrual_minor)}}；到账按独立资金记录核对。</p><article v-for="a in assignments" :key="String(a.id)" class="business-detail-item"><p>{{display(a.current_status)}} · 明确范围内的受派工作</p><p class="identifier">受派账号 {{(a.data as BusinessData)?.account_id}}</p><RouterLink v-if="(a.data as BusinessData)?.booking_id" :to="`/auditions/bookings/${(a.data as BusinessData).booking_id}`" class="button-link outline">读取本次受派试镜</RouterLink><RouterLink v-if="(a.data as BusinessData)?.order_id" :to="`/trade/orders/${(a.data as BusinessData).order_id}`" class="button-link outline">读取本次受派商单</RouterLink></article><p v-if="record.history_preserved" class="business-muted">历史派单保留。成员可读范围按逐人授权与本人受派事项核对。</p></section><section v-if="domain==='engagement'&&Object.keys(boards).length" class="business-boards"><h3>本期六项独立榜单</h3><section v-for="(label,key) in boardNames" :key="key"><h3>{{label}}</h3><ol v-if="boards[key]?.length"><li v-for="(r,i) in boards[key]" :key="String(r.person_id)"><span>第{{i+1}}位 · 已核验人物</span><span>光环 {{r.halo}} · 接片成长 {{r.growth_points}} · 本期分值 {{r.score}}</span><small class="identifier">{{r.person_id}}</small></li></ol><p v-else class="business-muted">本期没有满足条件的记录。</p></section></section><section v-if="domain==='engagement'&&Array.isArray(record.candidates)" class="business-candidates"><h3>本期已审候选人</h3><article v-for="(candidate,i) in (record.candidates as BusinessData[])" :key="String(candidate.id)"><p>候选人 {{i+1}} · 原榜单分值 {{candidate.ranking_score}}</p><p class="identifier">{{candidate.person_id}}</p></article><p>每票 {{(record.rules as BusinessData)?.vote_cost}} 晶钻 · 每日上限 {{(record.rules as BusinessData)?.daily_cap}} 票。实际投票资格由服务器核对。</p></section><section v-if="domain==='participation'&&Object.keys(terms).length"><h3>本版参演使用约定</h3><p>{{display(terms.mode)}} · {{display(terms.usage)}} · {{terms.territory}} · {{terms.language}}</p><p>有效截止 {{display(terms.valid_until)}} · {{terms.exclusive?'具有明确排他限制':'本约定非排他'}}</p><h3>禁止用途</h3><p>{{terms.prohibited_uses}}</p><h3>取消、保留与退款约定</h3><p>{{terms.cancellation_terms}}</p></section><section v-if="domain==='participation'&&Array.isArray(revenue.shares)"><h3>本版未来渠道净收入比例</h3><p v-for="r in (revenue.shares as BusinessData[])" :key="String(r.party_id)">{{display(r.role)}} · {{Number(r.bps)/100}}% <span class="identifier">{{r.party_id}}</span></p><p>仅针对未来实际核实的渠道净收入；固定片酬和当次平台费用分别核对。</p></section><section v-if="domain==='wallet'&&record.membership"><h3>实际星探资格</h3><p>{{(record.membership as BusinessData).active?'当前有效':'当前未生效或已过期'}} · 当前等级 {{(record.membership as BusinessData).level}}</p><p>有效截止 {{display((record.membership as BusinessData).valid_until)}}</p></section><section v-if="domain==='privacy'&&record.proposed_change"><h3>本次确认后将改为</h3><p>{{(record.proposed_change as BusinessData).display_name}}</p><p>本内容属于当前方案版本；历史合同与订单不随本次更名改写。</p></section><section v-if="domain==='privacy'&&request.type"><p>{{display(request.type)}} · 本次请求范围 {{(request.scopes as string[]).map(x=>display(x)).join('、')}}</p><p>平台答复目标日期：{{record.response_due_on}}。实际处理与答复分别核对。</p></section><section v-if="domain==='privacy'&&result.response"><h3>已复核答复</h3><p>{{result.response}}</p><p v-for="(remaining,i) in (result.remaining_actions as string[]||[])" :key="i">尚待完成：{{remaining}}</p></section><p v-if="domain==='privacy'" class="business-muted">回复、独立复核与实际执行分别记录；只有已确认执行结果才表示相应对象完成处理。</p><p v-if="domain==='media'" class="business-muted">{{record.current_status==='EXECUTED'?'任务有实际执行回执，请继续核对结果及对应文件。':'任务尚未形成可确认的执行结果。'}}</p></div></template>
